+func TestEOLSupportWindows(t *testing.T) {
+	standardEnd := time.Date(2025, 6, 30, 23, 59, 59, 0, time.UTC)
+	extendedEnd := time.Date(2028, 6, 30, 23, 59, 59, 0, time.UTC)
+	eol := EOL{StandardSupportUntil: standardEnd, ExtendedSupportUntil: extendedEnd}
+	tests := []struct {
+		name          string
+		now           time.Time
+		standardEnded bool
+		extendedEnded bool
+	}{
+		{name: "standard end", now: standardEnd},
+		{name: "extended support", now: standardEnd.Add(time.Second), standardEnded: true},
+		{name: "extended end", now: extendedEnd, standardEnded: true},
+		{name: "after extended end", now: extendedEnd.Add(time.Second), standardEnded: true, extendedEnded: true},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			if got := eol.IsStandardSupportEnded(tt.now); got != tt.standardEnded {
+				t.Errorf("IsStandardSupportEnded() = %v, want %v", got, tt.standardEnded)
+			}
+			if got := eol.IsExtendedSupportEnded(tt.now); got != tt.extendedEnded {
+				t.Errorf("IsExtendedSupportEnded() = %v, want %v", got, tt.extendedEnded)
+			}
+		})
+	}
