			amazon.Distro = config.Distro{Family: constant.Amazon, Release: tt.release}
			if got := amazon.depsFast(); !reflect.DeepEqual(got, tt.want) {
				t.Errorf("depsFast() = %v, want %v", got, tt.want)
			}
			if got := amazon.depsFastRoot(); !reflect.DeepEqual(got, tt.want) {
