func TestIsAmazonLinux2023OrLater(t *testing.T) {
	tests := []struct {
		family, release string
		want            bool
	}{
		{constant.Amazon, "2018.03", false},
		{constant.Amazon, "2 (Karoo)", false},
		{constant.Amazon, "2022 (Amazon Linux)", false},
		{constant.Amazon, "2023 (Amazon Linux 2023)", true},
		{constant.Amazon, "2025 (Amazon Linux)", true},
		{constant.Amazon, "2029 (Amazon Linux)", true},
		{constant.Amazon, "unknown", false},
		{constant.RedHat, "2023", false},
	}
	for _, tt := range tests {
		distro := config.Distro{Family: tt.family, Release: tt.release}
		if got := isAmazonLinux2023OrLater(distro); got != tt.want {
			t.Errorf("isAmazonLinux2023OrLater(%v) = %t, want %t", distro, got, tt.want)
		}
	}
